using System.Text.Json;
using HRPortal.Data; using HRPortal.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HRPortal.Controllers;
[Authorize(Policy="Suggestions.Submit")]
public class SuggestionsController(HRPortalDbContext db,IWebHostEnvironment env):Controller {
 static readonly string[] Categories=["بهبود فرایند و روش انجام کار","کاهش هزینه و صرفه‌جویی","افزایش بهره‌وری و کاهش زمان","ارتقای کیفیت محصول یا خدمت","ایمنی، بهداشت و محیط زیست","نگهداری و تعمیرات","فناوری اطلاعات و تحول دیجیتال","منابع انسانی و امور اداری","انرژی و منابع","سایر"];
 static readonly string[] Benefits=["کاهش هزینه","افزایش بهره‌وری","کاهش زمان","ارتقای کیفیت","کاهش ضایعات","افزایش ایمنی","رضایت کارکنان","رضایت مشتری","شفافیت و نظم اطلاعات","حفاظت از محیط زیست","سایر"];
 static readonly string[] Resources=["بدون هزینه یا منبع اضافی","نیروی انسانی","تجهیزات و ماشین‌آلات","نرم‌افزار و فناوری اطلاعات","مواد و ملزومات","بودجه مالی","آموزش","سایر"];
 bool Actor(out int id)=>int.TryParse(User.FindFirst("EmployeeId")?.Value,out id);
 void Lists(){ViewBag.Categories=Categories;ViewBag.Benefits=Benefits;ViewBag.Resources=Resources;}
 [HttpGet] public async Task<IActionResult> Index(){if(!Actor(out var id))return Forbid();return View(await db.Suggestions.AsNoTracking().Where(x=>x.ProposerEmployeeId==id).OrderByDescending(x=>x.UpdatedAtUtc).Take(100).ToListAsync());}
 [HttpGet] public async Task<IActionResult> Create(int? id,int step=1){if(!Actor(out var actor))return Forbid();var m=new SuggestionFormVm();if(id.HasValue){var x=await db.Suggestions.Include(x=>x.Members).Include(x=>x.Attachments).FirstOrDefaultAsync(x=>x.Id==id&&x.ProposerEmployeeId==actor);if(x==null)return NotFound();if(x.Status!="Draft")return RedirectToAction(nameof(Details),new{id});m=new(){Id=x.Id,Title=x.Title,Category=x.Category,RelatedArea=x.RelatedArea,ShortDescription=x.ShortDescription,ProblemDescription=x.ProblemDescription,ProposedSolution=x.ProposedSolution,Benefits=JsonSerializer.Deserialize<List<string>>(x.BenefitsJson)??[],BenefitDetails=x.BenefitDetails,ImplementationScope=x.ImplementationScope,ImplementationMethod=x.ImplementationMethod,ResourceTypes=JsonSerializer.Deserialize<List<string>>(x.ResourceTypesJson)??[],ResourceDetails=x.ResourceDetails,SelectedEmployeeIds=x.Members.Select(z=>z.EmployeeId).ToList(),Attachments=x.Attachments.ToList()};}m.CurrentStep=Math.Clamp(step,1,2);m.EmployeeOptions=await Options(m.SelectedEmployeeIds,actor);Lists();return View(m);}
 [HttpGet] public async Task<IActionResult> SearchEmployees(string? term){if(!Actor(out var actor))return Forbid();var q=db.Employees.AsNoTracking().Where(x=>x.Id!=actor&&x.Status=="فعال"&&x.IsSystemUser);if(!string.IsNullOrWhiteSpace(term)){var t=term.Trim();q=q.Where(x=>x.FirstName.Contains(t)||x.LastName.Contains(t)||x.PersonnelNumber.Contains(t)||(x.FirstName+" "+x.LastName).Contains(t));}return Json(await q.OrderBy(x=>x.LastName).ThenBy(x=>x.FirstName).Take(15).Select(x=>new{id=x.Id,name=x.FirstName+" "+x.LastName,personnelNumber=x.PersonnelNumber,organization=x.OrganizationUnit!=null?x.OrganizationUnit.Title:x.OrganizationDepartment!=null?x.OrganizationDepartment.Title:"—"}).ToListAsync());}
 [HttpGet] public async Task<IActionResult> Details(int id){if(!Actor(out var actor))return Forbid();var x=await db.Suggestions.AsNoTracking().Include(x=>x.Members).Include(x=>x.Attachments).FirstOrDefaultAsync(x=>x.Id==id&&x.ProposerEmployeeId==actor);return x==null?NotFound():View(x);}
 [HttpPost,ValidateAntiForgeryToken,RequestSizeLimit(25000000)] public async Task<IActionResult> Save(SuggestionFormVm m,bool submit,List<IFormFile>? files){if(!Actor(out var actor))return Forbid();if(!await db.Employees.AnyAsync(x=>x.Id==actor&&x.Status=="فعال"&&x.IsSystemUser))return Forbid();Suggestion? x=null;if(m.Id.HasValue){x=await db.Suggestions.Include(z=>z.Members).Include(z=>z.Attachments).FirstOrDefaultAsync(z=>z.Id==m.Id&&z.ProposerEmployeeId==actor);if(x==null)return NotFound();if(x.Status!="Draft")return Forbid();}else{x=new(){ProposerEmployeeId=actor,SuggestionNumber="TEMP"};db.Suggestions.Add(x);}
 m.SelectedEmployeeIds=(m.SelectedEmployeeIds??[]).Where(z=>z>0&&z!=actor).Distinct().Take(4).ToList();var people=await db.Employees.AsNoTracking().Where(z=>m.SelectedEmployeeIds.Contains(z.Id)&&z.Status=="فعال"&&z.IsSystemUser).Select(z=>new{z.Id,z.FirstName,z.LastName,z.PersonnelNumber}).ToListAsync();if(people.Count!=m.SelectedEmployeeIds.Count)ModelState.AddModelError("SelectedEmployeeIds","فقط کارکنان فعال قابل انتخاب هستند.");
 if(submit){if(string.IsNullOrWhiteSpace(m.Title)||m.Title.Trim().Length>200)ModelState.AddModelError("Title","عنوان الزامی و حداکثر ۲۰۰ نویسه است.");if(!Categories.Contains(m.Category))ModelState.AddModelError("Category","دسته‌بندی معتبر انتخاب کنید.");if(string.IsNullOrWhiteSpace(m.ShortDescription)||m.ShortDescription.Length>500)ModelState.AddModelError("ShortDescription","شرح کوتاه الزامی و حداکثر ۵۰۰ نویسه است.");if(string.IsNullOrWhiteSpace(m.ProblemDescription))ModelState.AddModelError("ProblemDescription","شرح مسئله الزامی است.");if(string.IsNullOrWhiteSpace(m.ProposedSolution))ModelState.AddModelError("ProposedSolution","راه‌حل پیشنهادی الزامی است.");}
 if(!ModelState.IsValid){m.Id=x.Id==0?null:x.Id;m.CurrentStep=submit?2:1;m.EmployeeOptions=await Options(m.SelectedEmployeeIds,actor);Lists();return View("Create",m);}
 x.Title=(m.Title??"").Trim();x.Category=m.Category??"";x.RelatedArea=m.RelatedArea?.Trim();x.ShortDescription=m.ShortDescription??"";x.ProblemDescription=m.ProblemDescription??"";x.ProposedSolution=m.ProposedSolution??"";x.BenefitsJson=JsonSerializer.Serialize((m.Benefits??[]).Where(Benefits.Contains).Distinct());x.BenefitDetails=m.BenefitDetails;x.ImplementationScope=m.ImplementationScope;x.ImplementationMethod=m.ImplementationMethod;x.ResourceTypesJson=JsonSerializer.Serialize((m.ResourceTypes??[]).Where(Resources.Contains).Distinct());x.ResourceDetails=m.ResourceDetails;x.UpdatedAtUtc=DateTime.UtcNow;
 if(x.Id==0){await db.SaveChangesAsync();x.SuggestionNumber=$"PISH-{DateTime.UtcNow:yyyy}-{x.Id:000000}";}
 db.SuggestionMembers.RemoveRange(x.Members);foreach(var p in people)x.Members.Add(new(){EmployeeId=p.Id,EmployeeNameSnapshot=p.FirstName+" "+p.LastName,PersonnelNumberSnapshot=p.PersonnelNumber});
 if(files!=null){var exts=new HashSet<string>(StringComparer.OrdinalIgnoreCase){".pdf",".doc",".docx",".xls",".xlsx",".png",".jpg",".jpeg"};var folder=Path.Combine(env.WebRootPath??Path.Combine(env.ContentRootPath,"wwwroot"),"uploads","suggestions",x.Id.ToString());Directory.CreateDirectory(folder);foreach(var f in files.Where(z=>z.Length>0)){var ext=Path.GetExtension(f.FileName);if(!exts.Contains(ext)||f.Length>10*1024*1024)continue;var name=Guid.NewGuid().ToString("N")+ext.ToLowerInvariant();await using var s=System.IO.File.Create(Path.Combine(folder,name));await f.CopyToAsync(s);x.Attachments.Add(new(){OriginalFileName=Path.GetFileName(f.FileName),StoredFileName=name,ContentType=f.ContentType??"application/octet-stream",FileSize=f.Length});}}
 if(submit){x.Status="Submitted";x.SubmittedAtUtc=DateTime.UtcNow;}await db.SaveChangesAsync();TempData["Success"]=submit?"پیشنهاد ثبت شد. شماره پیگیری: "+x.SuggestionNumber:"پیش‌نویس ذخیره شد.";return RedirectToAction(submit?nameof(Details):nameof(Create),new{id=x.Id});}
 [HttpGet] public async Task<IActionResult> Download(int id){if(!Actor(out var actor))return Forbid();var f=await db.SuggestionAttachments.Include(z=>z.Suggestion).FirstOrDefaultAsync(z=>z.Id==id&&z.Suggestion!.ProposerEmployeeId==actor);if(f==null)return NotFound();var p=Path.Combine(env.WebRootPath??Path.Combine(env.ContentRootPath,"wwwroot"),"uploads","suggestions",f.SuggestionId.ToString(),f.StoredFileName);return System.IO.File.Exists(p)?PhysicalFile(p,f.ContentType,f.OriginalFileName):NotFound();}
 async Task<List<SuggestionEmployeeOption>> Options(IEnumerable<int> ids,int actor){var a=ids.Distinct().ToArray();return await db.Employees.AsNoTracking().Where(x=>a.Contains(x.Id)&&x.Id!=actor).Select(x=>new SuggestionEmployeeOption{Id=x.Id,Name=x.FirstName+" "+x.LastName,PersonnelNumber=x.PersonnelNumber,Organization=x.OrganizationUnit!=null?x.OrganizationUnit.Title:x.OrganizationDepartment!=null?x.OrganizationDepartment.Title:"—"}).ToListAsync();}
}
